// Written with the help of Claude
// AI Usage Note: generated by Claude; checked against a saved Nominatim response by running the tests.
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { NominatimGeocoder, searchableAddress } from '../../dist/infra/geocoding/nominatim-geocoder.js';
import { savedPagesClient } from './fixtures/provider-pages.ts';

const VENUE = { name: 'Національна філармонія України', address: 'Володимирський узвіз, 2, Київ' };
const NOTED = { name: 'Behave space', address: 'Верхній Вал 48/28, код від домофона 2, 2 поверх, Київ' };

describe('NominatimGeocoder', () => {
  test('gives the coordinates of the first result, searched within Kyiv', async () => {
    const http = savedPagesClient({ '/search': 'nominatim/search.json' });

    const location = await new NominatimGeocoder(http).locate(VENUE);

    assert.deepEqual(location, { lat: 50.4533314, lng: 30.5282201 });
    const query = new URL(http.requested[0] ?? '').searchParams;
    assert.equal(query.get('q'), VENUE.address);
    assert.equal(query.get('countrycodes'), 'ua');
    assert.equal(query.get('bounded'), '1');
  });

  test('searches without the address notes, then by the venue name, and gives nothing when none finds it', async () => {
    const http = savedPagesClient({ '/search': { status: 200, text: '[]' } });

    const location = await new NominatimGeocoder(http).locate(NOTED);

    assert.equal(location, undefined);
    assert.deepEqual(
      http.requested.map((url) => new URL(url).searchParams.get('q')),
      [NOTED.address, 'Верхній Вал 48/28, Київ', 'Behave space, Київ'],
    );
  });

  test('asks once for an address that has nothing to clean', async () => {
    const http = savedPagesClient({ '/search': { status: 200, text: '[]' } });

    await new NominatimGeocoder(http).locate(VENUE);

    assert.deepEqual(
      http.requested.map((url) => new URL(url).searchParams.get('q')),
      [VENUE.address, 'Національна філармонія України, Київ'],
    );
  });

  test('throws when Nominatim does not answer 200', async () => {
    const http = savedPagesClient({ '/search': { status: 429 } });

    await assert.rejects(new NominatimGeocoder(http).locate(VENUE), /Nominatim answered 429/);
  });
});

describe('searchableAddress', () => {
  // Addresses of Karabas venues the geocoder could not find as given.
  const cases = [
    { address: 'Верхній Вал 48/28, код від домофона 2, 2 поверх, Київ', result: 'Верхній Вал 48/28, Київ' },
    { address: 'пр.Академіка Глушкова, 1 ВДНГ, Київ', result: 'проспект Академіка Глушкова, 1, Київ' },
    { address: 'м. Київ, вул. Межигірська, 2, Київ', result: 'вул. Межигірська, 2, Київ' },
    { address: 'вул. Хрещатик, 7, ст.м. Майдан Незалежності, Київ', result: 'вул. Хрещатик, 7, Київ' },
    { address: 'Київ, вул. Богдана Хмельницького, 5, Київ', result: 'вул. Богдана Хмельницького, 5, Київ' },
    { address: 'вул. Хрещатик, 15/4 (Пасаж), Київ', result: 'вул. Хрещатик, 15/4, Київ' },
    { address: 'пр-т Берестейський, 37, Київ', result: 'проспект Берестейський, 37, Київ' },
    { address: 'Проспект Спепана Бандері, 34-В, 2 поверх, Київ', result: 'Проспект Спепана Бандері, 34-В, Київ' },
  ];

  for (const { address, result } of cases) {
    test(`reads "${address}" as "${result}"`, () => {
      assert.equal(searchableAddress(address), result);
    });
  }
});
